import{_ as a,o as i,c as n,aj as e}from"./chunks/framework.BdtAaXf2.js";const c=JSON.parse('{"title":"JSON-Server 入门教程","description":"","frontmatter":{},"headers":[],"relativePath":"前端技能/JSON-Server 极速入门教程/JSON-Server 极速入门教程.md","filePath":"前端技能/JSON-Server 极速入门教程/JSON-Server 极速入门教程.md","lastUpdated":1744440300000,"__rawMarkdown":"# JSON-Server 入门教程\\n\\n## 什么是 JSON-Server？\\n\\nJSON-Server 是一个零代码的 REST API 模拟工具，它可以在不到 30 秒的时间内为你创建一个完整的假 REST API。它非常适合前端开发者在没有后端支持的情况下进行开发和测试。\\n\\n## 快速开始\\n\\n### 1. 安装\\n\\n首先，确保你的电脑上已经安装了 Node.js。然后打开终端，运行以下命令：\\n\\n```bash\\nnpm install -g json-server\\n```\\n\\n### 2. 创建数据文件\\n\\n在你的项目目录中创建一个名为 `db.json` 的文件，这个文件将作为你的数据库。例如：\\n\\n```json\\n{\\n  \\"posts\\": [\\n    { \\"id\\": 1, \\"title\\": \\"我的第一篇博客\\", \\"author\\": \\"张三\\" },\\n    { \\"id\\": 2, \\"title\\": \\"学习心得\\", \\"author\\": \\"李四\\" }\\n  ],\\n  \\"comments\\": [\\n    { \\"id\\": 1, \\"body\\": \\"写得真好！\\", \\"postId\\": 1 },\\n    { \\"id\\": 2, \\"body\\": \\"受益匪浅\\", \\"postId\\": 2 }\\n  ]\\n}\\n```\\n\\n### 3. 启动服务器\\n\\n在终端中运行：\\n\\n```bash\\njson-server --watch db.json\\n```\\n\\n服务器将在 `http://localhost:3000` 启动。\\n\\n## 基本使用\\n\\n### 获取数据\\n\\n- 获取所有文章：\\n\\n  ```bash\\n  GET http://localhost:3000/posts\\n  ```\\n\\n- 获取特定文章：\\n  ```bash\\n  GET http://localhost:3000/posts/1\\n  ```\\n\\n### 添加数据\\n\\n```bash\\nPOST http://localhost:3000/posts\\nContent-Type: application/json\\n\\n{\\n  \\"title\\": \\"新文章\\",\\n  \\"author\\": \\"王五\\"\\n}\\n```\\n\\n### 更新数据\\n\\n```bash\\nPUT http://localhost:3000/posts/1\\nContent-Type: application/json\\n\\n{\\n  \\"title\\": \\"修改后的标题\\",\\n  \\"author\\": \\"张三\\"\\n}\\n```\\n\\n### 删除数据\\n\\n```bash\\nDELETE http://localhost:3000/posts/1\\n```\\n\\n## 高级功能\\n\\n### 1. 数据过滤\\n\\n- 获取浏览量大于 100 的文章：\\n  ```bash\\n  GET http://localhost:3000/posts?views_gt=100\\n  ```\\n\\n### 2. 分页\\n\\n- 获取第 2 页，每页 5 条数据：\\n  ```bash\\n  GET http://localhost:3000/posts?_page=2&_per_page=5\\n  ```\\n\\n### 3. 排序\\n\\n- 按浏览量降序排序：\\n  ```bash\\n  GET http://localhost:3000/posts?_sort=views&_order=desc\\n  ```\\n\\n### 4. 关联查询\\n\\n- 获取文章及其评论：\\n  ```bash\\n  GET http://localhost:3000/posts?_embed=comments\\n  ```\\n\\n## 实用技巧\\n\\n1. **自定义端口**：\\n\\n   ```bash\\n   json-server --watch db.json --port 3004\\n   ```\\n\\n2. **添加延迟**：\\n\\n   ```bash\\n   json-server --watch db.json --delay 2000\\n   ```\\n\\n3. **静态文件服务**：\\n   创建 `public` 文件夹，放入静态文件，它们会被自动提供。\\n\\n## 常见问题\\n\\n1. **数据没有更新？**\\n\\n   - 确保 `db.json` 文件有写入权限\\n   - 检查文件是否被其他程序占用\\n\\n2. **跨域问题？**\\n\\n   - 使用 `--no-cors` 参数启动服务器\\n\\n   ```bash\\n   json-server --watch db.json --no-cors\\n   ```\\n\\n3. **需要更多功能？**\\n   - 查看官方文档了解更多高级功能\\n   - 可以使用中间件扩展功能\\n\\n## 总结\\n\\nJSON-Server 是一个简单但功能强大的工具，它可以帮助你：\\n\\n- 快速搭建测试环境\\n- 模拟后端 API\\n- 进行前端开发测试\\n- 学习 REST API 概念\\n\\n现在你可以开始使用 JSON-Server 来加速你的开发流程了！\\n"}'),t={name:"前端技能/JSON-Server 极速入门教程/JSON-Server 极速入门教程.md"};function l(h,s,p,r,d,o){return i(),n("div",null,[...s[0]||(s[0]=[e("",40)])])}const u=a(t,[["render",l]]);export{c as __pageData,u as default};
